#include <Servo.h>  // 使用 Arduino Servo 函式庫
#include <Ultrasonic.h>  // 引入超聲波模塊函式庫

Servo servo2;  // 只保留一個伺服馬達
Ultrasonic ultrasonic(4, 5);  // Trig: D2, Echo: D3
int distance;
int lastDistance = 0;
int voice = 7;    
int angle = 0;
bool direction = true;
unsigned long previousMillis = 0;
const int interval = 8;  // 基礎時間間隔

// **函式：讀取穩定距離 (5 次取平均)**
int getStableDistance(int samples = 5) {
    long total = 0;
    int validCount = 0;
    
    for (int i = 0; i < samples; i++) {
        int d = ultrasonic.read();
        if (d > 0 && d < 400) {  // 過濾錯誤數據
            total += d;
            validCount++;
        }
        delay(10);
    }

    return (validCount > 0) ? total / validCount : -1;
}

void setup() {
    Serial.begin(115200);
    pinMode(voice, OUTPUT);  // 音響控制 Pin
    pinMode(6, OUTPUT);  // LED Pin
    servo2.attach(10);    // 只連接一個伺服馬達到 D10
}

void loop() {
    unsigned long currentMillis = millis();
    
    // **讀取穩定距離**
    distance = getStableDistance();  // 讀取穩定距離
    
    // **將距離值 (5~50cm) 轉換為 speedFactor (1~5)**
    int speedFactor = map(distance, 5, 50, 1, 5);
    speedFactor = constrain(speedFactor, 1, 5);  // 確保數值不會超出範圍

    if (currentMillis - previousMillis >= interval) {
        previousMillis = currentMillis;

        if (direction) {
            angle += speedFactor;  // 根據 speedFactor 增加角度
            if (angle >= 180) direction = false;
        } else {
            angle -= speedFactor;  // 根據 speedFactor 減少角度
            if (angle <= 0) direction = true;
        }

        servo2.write(angle);  // 只控制一個伺服馬達
    }

    // 避免數值跳動太快，僅當變化超過 5cm 才更新
    if (abs(distance - lastDistance) > 5) {
        lastDistance = distance;
        Serial.print("Filtered Distance: ");
        Serial.println(lastDistance);
    }

    // 如果距離小於 10cm，讓 PIN 13 和音響開啟
    digitalWrite(6, (lastDistance < 10) ? HIGH : LOW);
    digitalWrite(voice, (lastDistance < 10) ? HIGH : LOW);
}

