  Serial.print("Flash Size: ");
  Serial.print(flashSize / (1024 * 1024));  // 顯示為MB
  Serial.println(" MB");

  // 查詢剩餘的閃存空間
  uint32_t freeSpace = ESP.getFreeSketchSpace(); // 獲取剩餘程式空間
  Serial.print("Free Sketch Space: ");
  Serial.print(freeSpace / (1024));  // 顯示為KB
  Serial.println(" KB");
}

